const NOTE_ICONS=[['🌿','herb leaf nature'],['🌱','seedling growth plant'],['🪷','lotus meditation'],['🌸','cherry blossom flower'],['🌳','tree forest'],['🌊','water wave ocean'],['🧘','yoga meditation calm'],['☀️','sun sunshine'],['🌙','moon night'],['🦋','butterfly'],['🐝','bee'],['🐢','turtle'],['🦉','owl'],['🦊','fox'],['🐼','panda'],['🐬','dolphin'],['🍎','apple fruit'],['🥑','avocado'],['🥕','carrot'],['🍵','tea'],['☕','coffee'],['🍞','bread'],['🌾','rice farm'],['🪴','potted plant'],['🏕️','camping retreat'],['⛺','tent'],['🏡','house home'],['⛰️','mountain'],['🏝️','island'],['🌅','sunrise'],['🌈','rainbow'],['💧','droplet water'],['❄️','snowflake'],['🔥','fire'],['❤️','heart love'],['💚','green heart'],['💜','purple heart'],['🤍','white heart'],['🤝','handshake team'],['🙏','prayer gratitude'],['🎨','art palette'],['🖌️','paintbrush'],['📷','camera'],['🎬','movie film'],['🎵','music'],['🎹','piano'],['🎸','guitar'],['📚','books study'],['📝','memo writing'],['📖','book read'],['🎓','graduation education'],['🔬','microscope science'],['💻','computer laptop'],['📱','phone'],['💡','idea bulb'],['🧩','puzzle'],['🎯','target goal'],['🧭','compass'],['🚀','rocket launch'],['📦','package inventory'],['🛠️','tools repair'],['⚙️','gear settings'],['💎','gem diamond'],['🏆','trophy award'],['🎁','gift'],['🎈','balloon'],['🧵','thread craft'],['🧶','yarn'],['🧺','basket'],['🕯️','candle'],['🕊️','dove peace'],['☯','yin yang balance']];
const noteFormBeforeGantt=noteForm;noteForm=function(n){noteFormBeforeGantt(n);const small=$('.note-composer>small');if(small)small.textContent='Tệp đính kèm tối đa 25 MB';};
const notesBeforeGantt=notesPage;notesPage=function(){return notesBeforeGantt().replace(/<article class="keep-card"/g,'<article tabindex="0" role="button" class="keep-card"').replace(/<small>/g,'<small>');};
function openClickedNote(e){const card=e.target.closest('.keep-card');if(!card||e.target.closest('button,a,input,textarea,audio,video'))return;const id=card.querySelector('[data-note-edit]')?.dataset.noteEdit,n=data.notes?.find(n=>n.id===id);if(n)noteForm(n);}
document.addEventListener('click',openClickedNote);document.addEventListener('keydown',e=>{if(e.target.matches('.keep-card')&&['Enter',' '].includes(e.key)){e.preventDefault();openClickedNote(e);}});
const projectFormBeforeIcons=projectForm;projectForm=function(p){projectFormBeforeIcons(p);const panel=$('.icon-picker-panel');if(!panel)return;panel.insertAdjacentHTML('afterbegin','<input class="emoji-search" placeholder="Search icons: leaf, flower, music…" aria-label="Search icons in English"><div class="emoji-results"></div>');const search=panel.querySelector('.emoji-search'),results=panel.querySelector('.emoji-results');function draw(){const q=search.value.trim().toLowerCase();results.innerHTML=NOTE_ICONS.filter(([icon,name])=>!q||name.includes(q)).map(([icon,name])=>'<button type="button" title="'+name+'" data-extra-icon="'+icon+'">'+icon+'</button>').join('')||'<small>No icons found</small>';}search.oninput=draw;results.onclick=e=>{const b=e.target.closest('[data-extra-icon]');if(!b)return;$('#editor-form').elements.icon.value=b.dataset.extraIcon;$('#project-icon-preview').textContent=b.dataset.extraIcon;panel.closest('details').open=false;};draw();};
function ganttEdges(p){return (p.dependencies||[]).filter(e=>p.tasks.some(t=>t.id===e.from)&&p.tasks.some(t=>t.id===e.to));}
function addGanttEdge(p,from,to){if(from===to||!p.tasks.some(t=>t.id===from)||!p.tasks.some(t=>t.id===to))return false;const edges=ganttEdges(p);if(edges.some(e=>e.from===from&&e.to===to))return false;const stack=[to],seen=new Set();while(stack.length){const id=stack.pop();if(id===from)return false;if(seen.has(id))continue;seen.add(id);edges.filter(e=>e.from===id).forEach(e=>stack.push(e.to));}if(edges.length>=1000)return false;p.dependencies=[...edges,{from,to}];save();return true;}
let ganttFrom=null;
function ganttPage(){const p=project()||visibleProjects()[0];if(!p)return heading('TIẾN TRÌNH','Gantt','Tạo dự án để bắt đầu.');const scheduled=p.tasks.filter(t=>t.start||t.end||t.due),dates=scheduled.flatMap(t=>[t.start?.slice(0,10)||t.end?.slice(0,10)||t.due,t.end?.slice(0,10)||t.due||t.start?.slice(0,10)]).sort(),first=dates[0]||today(),last=dates.at(-1)||today(),span=Math.max(7,Math.ceil((Date.parse(last)-Date.parse(first))/86400000)+1),scale=Math.max(4,Math.min(32,1200/span)),width=Math.max(700,span*scale),row=54,items=scheduled.map((t,i)=>{const start=t.start?.slice(0,10)||t.end?.slice(0,10)||t.due,end=t.end?.slice(0,10)||t.due||start;return {t,x:(Date.parse(start)-Date.parse(first))/86400000*scale,y:i*row+48,w:Math.max(14,((Date.parse(end)-Date.parse(start))/86400000+1)*scale)};}),edges=ganttEdges(p);return heading('TIẾN TRÌNH DỰ ÁN','Gantt',esc(p.name))+projectSummary(p)+'<p class="help-copy">Kéo chấm ở cuối thanh sang công việc kế tiếp để nối. Có thể chạm lần lượt hai chấm. Mũi tên chỉ quan hệ hoàn thành → bắt đầu; lịch không tự đổi. Bấm mũi tên để gỡ.</p><div class="gantt-scroll"><div class="gantt-layout" style="width:'+(width+240)+'px"><div class="gantt-labels"><strong>Công việc</strong>'+items.map(i=>'<button data-task="'+esc(i.t.id)+'" data-pid="'+esc(p.id)+'">'+esc(i.t.title)+'</button>').join('')+'</div><svg class="gantt-svg" width="'+width+'" height="'+(items.length*row+50)+'" viewBox="0 0 '+width+' '+(items.length*row+50)+'"><defs><marker id="gantt-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#9876b7"/></marker></defs>'+Array.from({length:Math.min(100,span)},(_,i)=>{const step=Math.max(1,Math.ceil(span/100)),day=i*step;if(day>=span)return '';const label=new Date(Date.parse(first)+day*86400000).toLocaleDateString('vi-VN',{day:'numeric',month:'numeric'});return '<text x="'+(day*scale+3)+'" y="20" font-size="10">'+label+'</text><path d="M'+day*scale+' 30V'+(items.length*row+50)+'" stroke="#eee8f3"/>';}).join('')+edges.map((e,index)=>{const a=items.find(i=>i.t.id===e.from),b=items.find(i=>i.t.id===e.to);if(!a||!b)return '';return '<path class="gantt-edge" tabindex="0" role="button" aria-label="Gỡ liên kết '+esc(a.t.title)+' đến '+esc(b.t.title)+'" data-gantt-remove="'+index+'" data-gantt-p="'+esc(p.id)+'" d="M'+(a.x+a.w)+' '+(a.y+14)+' C'+(a.x+a.w+30)+' '+(a.y+14)+','+(b.x-30)+' '+(b.y+14)+','+b.x+' '+(b.y+14)+'" fill="none" stroke="#9876b7" stroke-width="2" marker-end="url(#gantt-arrow)"/>';}).join('')+items.map(i=>'<g><rect x="'+i.x+'" y="'+i.y+'" width="'+i.w+'" height="28" rx="8" fill="'+p.color+'22"/><rect x="'+i.x+'" y="'+i.y+'" width="'+i.w*taskPct(i.t)/100+'" height="28" rx="8" fill="'+p.color+'"/><text x="'+(i.x+6)+'" y="'+(i.y+19)+'" font-size="11">'+taskPct(i.t)+'%</text><circle tabindex="0" role="button" aria-label="Nối '+esc(i.t.title)+'" class="gantt-port" data-gantt-port="'+esc(i.t.id)+'" data-gantt-p="'+esc(p.id)+'" cx="'+(i.x+i.w)+'" cy="'+(i.y+14)+'" r="7" fill="#fff" stroke="'+p.color+'"/></g>').join('')+'</svg></div></div><section class="gantt-undated"><h3>Chưa đặt lịch</h3>'+workTaskList(p.tasks.filter(t=>!scheduled.includes(t)).map(t=>({...t,project:p})),2000)+'</section>';}
const ganttNav=document.createElement('button');ganttNav.className='nav';ganttNav.dataset.view='gantt';ganttNav.innerHTML=svgIcon('timeline')+' Gantt';document.querySelector('.sidebar nav').append(ganttNav);
const renderBeforeGantt=render;render=function(){renderBeforeGantt();if(view==='gantt'){$('#main').innerHTML=ganttPage();$('#crumb').textContent='Gantt';refreshDueAlerts();}};
document.addEventListener('click',e=>{const tab=e.target.closest('#tabs [data-project]');if(view==='gantt'&&tab){e.preventDefault();e.stopImmediatePropagation();active=tab.dataset.project;render();}},true);
document.addEventListener('pointerdown',e=>{const port=e.target.closest('[data-gantt-port]');if(port){if(!ganttFrom)ganttFrom={id:port.dataset.ganttPort,p:port.dataset.ganttP};port.classList.add('connecting');e.preventDefault();}});
document.addEventListener('pointerup',e=>{if(!ganttFrom)return;const port=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-gantt-port]');if(port&&port.dataset.ganttPort!==ganttFrom.id&&port.dataset.ganttP===ganttFrom.p){if(!addGanttEdge(project(ganttFrom.p),ganttFrom.id,port.dataset.ganttPort))notify('Liên kết không hợp lệ, trùng hoặc tạo vòng lặp.');ganttFrom=null;render();}});
document.addEventListener('click',e=>{const edge=e.target.closest('[data-gantt-remove]');if(edge){const p=project(edge.dataset.ganttP);modal('<h2>Gỡ liên kết công việc?</h2>',()=>{p.dependencies=ganttEdges(p).filter((_,i)=>i!==Number(edge.dataset.ganttRemove));save();$('#editor').close();render();});}});

const detailBeforeRename=resourceDetail;resourceDetail=function(f){detailBeforeRename(f);$('#editor-body .help-actions').insertAdjacentHTML('beforeend','<button type="button" class="btn" id="rename-resource">Đổi tên</button>');$('#rename-resource').onclick=()=>{modal('<h2>Đổi tên tài nguyên</h2>'+field('Tên tệp','name',f.name,'text',true,200),async fd=>{try{await requestAPI('resource-name','PUT',{id:f.id,source:f.source,name:fd.get('name')});f.name=fd.get('name').trim();$('#editor').close();resourceState.key='';loadResources(true);}catch(e){notify(e.message);}});};};

const saveBeforeDependencies=save;save=function(){for(const p of data.projects)if(p.dependencies)p.dependencies=ganttEdges(p);return saveBeforeDependencies();};
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const port=e.target.closest('[data-gantt-port]'),edge=e.target.closest('[data-gantt-remove]');if(edge){e.preventDefault();edge.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(port){e.preventDefault();if(ganttFrom&&ganttFrom.id!==port.dataset.ganttPort){addGanttEdge(project(port.dataset.ganttP),ganttFrom.id,port.dataset.ganttPort);ganttFrom=null;render();}else ganttFrom={id:port.dataset.ganttPort,p:port.dataset.ganttP};}});
